// RVJS 語料（tools/build.js 由 examples/*.s 產生，勿手動編輯）
// web/app.js 優先用它覆蓋下拉選單。
globalThis.RVJS_CORPUS = [
  { name: "branch", src: "# branch.s — 六種比較分支（beq/bne/blt/bge/bltu/bgeu）各測 taken 與 not-taken。\n# 全對則印 `OK` 且 exit 0；任一失敗則印 `FAIL` 且 exit 1。\n# 預期 UART(全對): OK\n# 預期 exit(全對): 0\n# 只用 RV32I + 偽指令 li/j。\n\n        # --- beq ---\n        li      t0, 5\n        li      t1, 5\n        beq     t0, t1, br_beq_t\n        j       br_fail\nbr_beq_t:\n        li      t1, 6\n        beq     t0, t1, br_fail  # 5 == 6？不該跳\n\n        # --- bne ---\n        bne     t0, t1, br_bne_t  # 5 != 6，該跳\n        j       br_fail\nbr_bne_t:\n        li      t1, 5\n        bne     t0, t1, br_fail  # 5 != 5？不該跳\n\n        # --- blt（有號）：-1 < 1 成立，1 < -1 不成立 ---\n        li      t0, -1\n        li      t1, 1\n        blt     t0, t1, br_blt_t\n        j       br_fail\nbr_blt_t:\n        blt     t1, t0, br_fail\n\n        # --- bge（有號）：1 >= -1 成立，-1 >= 1 不成立 ---\n        bge     t1, t0, br_bge_t\n        j       br_fail\nbr_bge_t:\n        bge     t0, t1, br_fail\n\n        # --- bltu（無號）：1 < 0xFFFFFFFF 成立，0xFFFFFFFF < 1 不成立 ---\n        bltu    t1, t0, br_bltu_t\n        j       br_fail\nbr_bltu_t:\n        bltu    t0, t1, br_fail\n\n        # --- bgeu（無號）：0xFFFFFFFF >= 1 成立，1 >= 0xFFFFFFFF 不成立 ---\n        bgeu    t0, t1, br_bgeu_t\n        j       br_fail\nbr_bgeu_t:\n        bgeu    t1, t0, br_fail\n\n        # --- 全對 ---\n        lui     s0, 0x10000     # s0 = 0x10000000 (UART)\n        li      t1, 79          # 'O'\n        sb      t1, 0(s0)\n        li      t1, 75          # 'K'\n        sb      t1, 0(s0)\n        li      a0, 0\n        li      a7, 10\n        ecall\n\nbr_fail:\n        lui     s0, 0x10000\n        li      t1, 70          # 'F'\n        sb      t1, 0(s0)\n        li      t1, 65          # 'A'\n        sb      t1, 0(s0)\n        li      t1, 73          # 'I'\n        sb      t1, 0(s0)\n        li      t1, 76          # 'L'\n        sb      t1, 0(s0)\n        li      a0, 1\n        li      a7, 10\n        ecall\n" },
  { name: "fib", src: "# fib.s — 迴圈求 fib(10) = 55（fib(0)=0, fib(1)=1），以十進位字元經 UART 印出，並以 exit code 55 結束。\n# 預期 UART: 55\n# 預期 exit: 55\n# 只用 RV32I + 偽指令 li/mv/j；s0 = UART base，s1 = 計算結果(留作 exit code)。\n\n        li      t0, 10          # t0 = n\n        li      t1, 0           # t1 = a = fib(0)\n        li      t2, 1           # t2 = b = fib(1)\n        li      t3, 2           # t3 = i\nfib_loop:\n        blt     t0, t3, fib_done  # n < i → 完成\n        add     t4, t1, t2      # t4 = a + b\n        mv      t1, t2\n        mv      t2, t4\n        addi    t3, t3, 1\n        j       fib_loop\nfib_done:\n        # t2 = fib(10) = 55\n        mv      s1, t2          # 留作 exit code\n        mv      t0, t2          # t0 = 待印數值\n        lui     s0, 0x10000     # s0 = 0x10000000 (UART)\n\n        # --- 以重複減法拆出百/十/個位 ---\n        li      t3, 100\n        li      t4, 0           # t4 = 百位數\nfib_h100:\n        blt     t0, t3, fib_h100_done\n        sub     t0, t0, t3\n        addi    t4, t4, 1\n        j       fib_h100\nfib_h100_done:\n        li      t3, 10\n        li      t5, 0           # t5 = 十位數\nfib_h10:\n        blt     t0, t3, fib_h10_done\n        sub     t0, t0, t3\n        addi    t5, t5, 1\n        j       fib_h10\nfib_h10_done:\n        # 前導零不印，至少印一位\n        li      t6, 0\n        beq     t4, t6, fib_no_hund\n        addi    t4, t4, 48\n        sb      t4, 0(s0)\n        addi    t5, t5, 48\n        sb      t5, 0(s0)\n        j       fib_print_ones\nfib_no_hund:\n        beq     t5, t6, fib_print_ones\n        addi    t5, t5, 48\n        sb      t5, 0(s0)\nfib_print_ones:\n        addi    t0, t0, 48\n        sb      t0, 0(s0)\n\n        mv      a0, s1          # exit code = 55\n        li      a7, 10\n        ecall\n" },
  { name: "hello", src: "# hello.s — 以 SB 寫 0x10000000 逐字印出 `Hi RV32!`，再以 ecall(a7=10) 結束。\n# 預期 UART: Hi RV32!\n# 預期 exit: 0\n# 只用 RV32I + 偽指令 li；s0 = UART base (0x10000000)。\n\n        lui     s0, 0x10000     # s0 = 0x10000000 (UART)\n\n        li      t1, 72          # 'H'\n        sb      t1, 0(s0)\n        li      t1, 105         # 'i'\n        sb      t1, 0(s0)\n        li      t1, 32          # ' '\n        sb      t1, 0(s0)\n        li      t1, 82          # 'R'\n        sb      t1, 0(s0)\n        li      t1, 86          # 'V'\n        sb      t1, 0(s0)\n        li      t1, 51          # '3'\n        sb      t1, 0(s0)\n        li      t1, 50          # '2'\n        sb      t1, 0(s0)\n        li      t1, 33          # '!'\n        sb      t1, 0(s0)\n\n        li      a0, 0           # exit code 0\n        li      a7, 10          # ecall: halt\n        ecall\n" },
  { name: "loadstore", src: "# loadstore.s — LW/SW/SB/LB 往返測試（含符號延伸、零延伸、小端位元組序）。\n# 全對則 a0=0 並印 `OK`；任一失敗則 a0=1 並印 `FAIL`。\n# 預期 UART(全對): OK\n# 預期 exit(全對): 0\n# 只用 RV32I + 偽指令 li；以 sp 指向的堆疊區作測試記憶體。\n\n        # sp 明確指向 RAM 高位（模擬器開機 sp=0，bare-metal 需自行初始化）\n        lui     sp, 0x10          # sp = 0x10000（程式碼在其下方）\n        addi    sp, sp, -16\n\n        # SW/LW 往返\n        li      t0, 12345\n        sw      t0, 0(sp)\n        lw      t1, 0(sp)\n        bne     t0, t1, ls_fail\n\n        # SB/LB 往返（含符號延伸）：-5 存位元組再讀回仍為 -5\n        li      t0, -5\n        sb      t0, 4(sp)\n        lb      t1, 4(sp)\n        bne     t0, t1, ls_fail\n\n        # SB/LBU 往返（零延伸）：200 讀回仍為 200\n        li      t0, 200\n        sb      t0, 5(sp)\n        lbu     t1, 5(sp)\n        bne     t0, t1, ls_fail\n\n        # 小端序檢查：0x01020304 的最低位位元組為 0x04，最高位為 0x01\n        lui     t0, 0x1020\n        addi    t0, t0, 0x304   # t0 = 0x01020304\n        sw      t0, 8(sp)\n        lb      t1, 8(sp)\n        li      t2, 4\n        bne     t1, t2, ls_fail\n        lb      t1, 11(sp)\n        li      t2, 1\n        bne     t1, t2, ls_fail\n\n        # --- 全對 ---\n        lui     s0, 0x10000     # s0 = 0x10000000 (UART)\n        li      t1, 79          # 'O'\n        sb      t1, 0(s0)\n        li      t1, 75          # 'K'\n        sb      t1, 0(s0)\n        li      a0, 0\n        li      a7, 10\n        ecall\n\nls_fail:\n        lui     s0, 0x10000\n        li      t1, 70          # 'F'\n        sb      t1, 0(s0)\n        li      t1, 65          # 'A'\n        sb      t1, 0(s0)\n        li      t1, 73          # 'I'\n        sb      t1, 0(s0)\n        li      t1, 76          # 'L'\n        sb      t1, 0(s0)\n        li      a0, 1\n        li      a7, 10\n        ecall\n" },
  { name: "mul", src: "# mul.s — M 擴充 mul：6 * 7 = 42，以十進位字元經 UART 印出，並以 exit code 42 結束。\n# 預期 UART: 42\n# 預期 exit: 42\n# 只用 RV32I + M(mul) + 偽指令 li/mv/j；s0 = UART base，s1 = 計算結果(留作 exit code)。\n\n        li      t1, 6\n        li      t2, 7\n        mul     t0, t1, t2      # t0 = 42\n\n        mv      s1, t0          # 留作 exit code\n        lui     s0, 0x10000     # s0 = 0x10000000 (UART)\n\n        # --- 以重複減法拆出百/十/個位 ---\n        li      t3, 100\n        li      t4, 0           # t4 = 百位數\nmul_h100:\n        blt     t0, t3, mul_h100_done\n        sub     t0, t0, t3\n        addi    t4, t4, 1\n        j       mul_h100\nmul_h100_done:\n        li      t3, 10\n        li      t5, 0           # t5 = 十位數\nmul_h10:\n        blt     t0, t3, mul_h10_done\n        sub     t0, t0, t3\n        addi    t5, t5, 1\n        j       mul_h10\nmul_h10_done:\n        # 前導零不印，至少印一位\n        li      t6, 0\n        beq     t4, t6, mul_no_hund\n        addi    t4, t4, 48\n        sb      t4, 0(s0)\n        addi    t5, t5, 48\n        sb      t5, 0(s0)\n        j       mul_print_ones\nmul_no_hund:\n        beq     t5, t6, mul_print_ones\n        addi    t5, t5, 48\n        sb      t5, 0(s0)\nmul_print_ones:\n        addi    t0, t0, 48\n        sb      t0, 0(s0)\n\n        mv      a0, s1          # exit code = 42\n        li      a7, 10\n        ecall\n" },
  { name: "sort", src: "# sort.s — 以氣泡排序將堆疊上的 5 個數 [5,3,4,1,2] 排成 [1,2,3,4,5]，\n# 再把排序結果以字元經 UART 印出，並以 exit code 0 結束。\n# 預期 UART: 12345\n# 預期 exit: 0\n# 只用 RV32I + 偽指令 li/j；s0 = UART base；數列放在 sp 指標的堆疊區。\n\n        # sp 明確指向 RAM 高位（模擬器開機 sp=0，bare-metal 需自行初始化）\n        lui     sp, 0x10          # sp = 0x10000（程式碼在其下方）\n        addi    sp, sp, -32\n        li      t0, 5\n        sw      t0, 0(sp)\n        li      t0, 3\n        sw      t0, 4(sp)\n        li      t0, 4\n        sw      t0, 8(sp)\n        li      t0, 1\n        sw      t0, 12(sp)\n        li      t0, 2\n        sw      t0, 16(sp)\n\n        li      t3, 5           # t3 = n\n        li      s3, 4           # s3 = n - 1（外圈上限）\n        li      t4, 0           # t4 = i（外圈）\nsort_outer:\n        sub     t5, t3, t4      # t5 = n - i\n        addi    t5, t5, -1      # t5 = n-1-i（內圈比較次數，恆 >= 1）\n        li      t6, 0           # t6 = j（內圈）\nsort_inner:\n        slli    s2, t6, 2       # s2 = j*4（位元組偏移）\n        add     s2, s2, sp      # s2 = &a[j]\n        lw      t1, 0(s2)       # t1 = a[j]\n        lw      t2, 4(s2)       # t2 = a[j+1]\n        blt     t2, t1, sort_swap  # a[j+1] < a[j] → 交換\n        j       sort_noswap\nsort_swap:\n        sw      t2, 0(s2)\n        sw      t1, 4(s2)\nsort_noswap:\n        addi    t6, t6, 1\n        blt     t6, t5, sort_inner\n        addi    t4, t4, 1\n        blt     t4, s3, sort_outer\n\n        # --- 印出排序結果（五數皆為個位數，直接加 '0'） ---\n        lui     s0, 0x10000     # s0 = 0x10000000 (UART)\n        lw      t0, 0(sp)\n        addi    t0, t0, 48\n        sb      t0, 0(s0)\n        lw      t0, 4(sp)\n        addi    t0, t0, 48\n        sb      t0, 0(s0)\n        lw      t0, 8(sp)\n        addi    t0, t0, 48\n        sb      t0, 0(s0)\n        lw      t0, 12(sp)\n        addi    t0, t0, 48\n        sb      t0, 0(s0)\n        lw      t0, 16(sp)\n        addi    t0, t0, 48\n        sb      t0, 0(s0)\n\n        li      a0, 0\n        li      a7, 10\n        ecall\n" },
  { name: "sum", src: "# sum.s — 計算 1+2+...+10 = 55，以十進位字元經 UART 印出，並以 exit code 55 結束。\n# 預期 UART: 55\n# 預期 exit: 55\n# 只用 RV32I + 偽指令 li/mv/j；s0 = UART base，s1 = 計算結果(留作 exit code)。\n\n        li      t0, 0           # t0 = sum\n        li      t1, 1           # t1 = i\n        li      t2, 11          # 上限(不含)\nsum_loop:\n        add     t0, t0, t1\n        addi    t1, t1, 1\n        blt     t1, t2, sum_loop\n\n        mv      s1, t0          # s1 = 55（留作 exit code）\n        lui     s0, 0x10000     # s0 = 0x10000000 (UART)\n\n        # --- 以重複減法拆出百/十/個位 ---\n        li      t3, 100\n        li      t4, 0           # t4 = 百位數\nsum_h100:\n        blt     t0, t3, sum_h100_done\n        sub     t0, t0, t3\n        addi    t4, t4, 1\n        j       sum_h100\nsum_h100_done:\n        li      t3, 10\n        li      t5, 0           # t5 = 十位數\nsum_h10:\n        blt     t0, t3, sum_h10_done\n        sub     t0, t0, t3\n        addi    t5, t5, 1\n        j       sum_h10\nsum_h10_done:\n        # 此時 t4=百位, t5=十位, t0=個位；前導零不印，至少印一位\n        li      t6, 0\n        beq     t4, t6, sum_no_hund\n        addi    t4, t4, 48\n        sb      t4, 0(s0)\n        addi    t5, t5, 48\n        sb      t5, 0(s0)\n        j       sum_print_ones\nsum_no_hund:\n        beq     t5, t6, sum_print_ones\n        addi    t5, t5, 48\n        sb      t5, 0(s0)\nsum_print_ones:\n        addi    t0, t0, 48\n        sb      t0, 0(s0)\n\n        mv      a0, s1          # exit code = 55\n        li      a7, 10\n        ecall\n" }
];
